import { useEffect, useState } from "react";
import API from "../api";

function Home() {
  const [events, setEvents] = useState([]);

  useEffect(() => {
    API.get("/events").then(res => setEvents(res.data.events));
  }, []);

  return (
    <div>
      <h2>All Events</h2>
      {events.map(e => (
        <div key={e._id}>
          <h3>{e.name}</h3>
          <p>{e.location}</p>
        </div>
      ))}
    </div>
  );
}

export default Home;
